-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_dual_bound_offer(p_offer_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_offer_id AND procedure = 'dual_bound_offer' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('dual_bound_offer', p_offer_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_dual_bound_offer(p_offer_id text, p_sponsor_id text, p_merchant_id text, p_contribution bigint, p_currency text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    -- (no computed values)
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_offer_id AND procedure = 'dual_bound_offer' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_offer_id AND procedure = 'dual_bound_offer' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_offer_id, 'dual_bound_offer')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;


    -- debit sponsor_commitment (sponsor.commitment)
    IF (p_contribution) < 0 THEN
        RAISE EXCEPTION 'negative money for sponsor_commitment';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('sponsor.commitment', p_sponsor_id, p_currency, -(p_contribution))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_contribution));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('dual_bound_offer', 'sponsor_commitment', 'sponsor.commitment', p_sponsor_id, p_contribution, p_currency, -(p_contribution), p_offer_id);

    -- credit merchant_expected_contribution (merchant.expected_contribution)
    IF (p_contribution) < 0 THEN
        RAISE EXCEPTION 'negative money for merchant_expected_contribution';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('merchant.expected_contribution', p_merchant_id, p_currency, p_contribution)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_contribution);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('dual_bound_offer', 'merchant_expected_contribution', 'merchant.expected_contribution', p_merchant_id, p_contribution, p_currency, p_contribution, p_offer_id);

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'dual_bound_offer' AND idempotency_key = p_offer_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_offer_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('dual_bound_offer', p_offer_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
